{
  "title": "ChatHealthy.ai — Business Architecture",
  "subtitle": "Find Care. Evaluate Care. Discuss Care.",
  "version": "1.0",
  "date": "2026-03-31",
  "executive_summary": "ChatHealthy.ai is a consumer-first healthcare navigation platform structured around a simple but underbuilt reality: people must find care, evaluate options, and make decisions—often with others. Existing solutions fragment this journey across search engines, provider directories, ratings sites, and disconnected conversations. ChatHealthy integrates these steps into a single architecture designed for clarity, trust, and decision support.\n\nThe platform consists of three tightly coupled components. Find Care provides free, high-quality provider discovery. Evaluate Care builds trust through structured analysis of provider quality and clinical options. Discuss Care introduces a new category: multi-participant, AI-assisted healthcare decision-making. This final component transforms passive research into active collaboration, where families and caregivers make decisions together with AI support.\n\nThe business model aligns with governance constraints: no care-chain revenue. Instead, ChatHealthy monetizes through premium AI usage and AI vendor partnerships. AI companies pay to participate in high-value healthcare decision contexts, while users retain control and pay only for optional premium AI engagement. The result is a platform that owns the healthcare decision room without compromising neutrality.",
  "mission": "Help people make better healthcare decisions together.",
  "components": {
    "find_care": {
      "name": "Find Care",
      "tagline": "Find the right care, fast",
      "description": "Find Care is the entry point into the platform, enabling users to locate healthcare providers, specialties, and services with precision. It uses vector search and taxonomy matching to interpret user intent and map it to relevant providers across geographies. The system is designed to reduce friction in navigating the healthcare system, especially for users unfamiliar with medical terminology or care pathways.",
      "capabilities": [
        "Natural language provider search",
        "Specialty and condition mapping",
        "Geographic filtering (DE, MS, VA expanding to all states)",
        "Provider detail lookup",
        "Healthcare system navigation guidance"
      ],
      "data_sources": [
        "NPI Registry",
        "State provider registries",
        "Internal taxonomy and vector embeddings"
      ],
      "pricing": "free forever",
      "role_in_value_chain": "the funnel"
    },
    "evaluate_care": {
      "name": "Evaluate Care",
      "tagline": "Understand your options",
      "description": "Evaluate Care helps users assess healthcare options using structured data and AI synthesis. It aggregates provider credentials, clinical trial availability, and quality indicators into a unified view. The system translates complex, multi-source data into consumer-comprehensible insights while maintaining transparency of underlying signals.",
      "capabilities": [
        "Provider credential analysis",
        "Clinical trial discovery and matching",
        "Quality signal aggregation",
        "Comparative provider evaluation",
        "Explainable AI summaries of provider quality"
      ],
      "data_sources": [
        "NPI Registry",
        "ClinicalTrials.gov",
        "State medical boards",
        "CMS quality data",
        "Public disciplinary records"
      ],
      "pricing": "free now, paywall post-trust",
      "patent_concept": {
        "claim": "Method for synthesizing healthcare provider quality signals using large language models to produce consumer-comprehensible provider assessments",
        "signals": [
          "NPI data",
          "board certifications",
          "disciplinary actions",
          "malpractice history",
          "patient outcomes",
          "clinical trial participation",
          "prescription patterns",
          "CMS quality scores",
          "state licensing records"
        ],
        "innovation": "Structured synthesis of heterogeneous public healthcare quality signals into explainable consumer-facing assessments using LLMs",
        "status": "pre-provisional"
      },
      "role_in_value_chain": "trust builder"
    },
    "discuss_care": {
      "name": "Discuss Care",
      "tagline": "Decide together",
      "description": "Discuss Care is a multi-participant, AI-assisted healthcare collaboration environment. Users invite family, friends, and caregivers into a shared session where humans and multiple AI models interact in real time. All participants have access to the same tools and data, enabling informed, collective decision-making. The system enforces healthcare-specific guardrails and structured interaction to maintain clarity, safety, and focus.",
      "features": [
        {
          "id": "DC-01",
          "name": "Shared Chat Session",
          "description": "Multiple humans collaborate in a single AI-assisted conversation"
        },
        {
          "id": "DC-02",
          "name": "Invite System",
          "description": "Link-based access for participants without requiring accounts"
        },
        {
          "id": "DC-03",
          "name": "Multi-Model AI",
          "description": "Multiple AI systems participate simultaneously in the same session"
        },
        {
          "id": "DC-04",
          "name": "Shared Tool Access",
          "description": "All participants can invoke healthcare tools within the session"
        },
        {
          "id": "DC-05",
          "name": "Healthcare Guardrails",
          "description": "Conversations constrained to healthcare navigation with safety enforcement"
        },
        {
          "id": "DC-06",
          "name": "Session Transcript",
          "description": "Exportable record for sharing with providers and care teams"
        },
        {
          "id": "DC-07",
          "name": "Consent per Participant",
          "description": "Each participant controls their own data sharing and permissions"
        },
        {
          "id": "DC-08",
          "name": "Participant Roles",
          "description": "Host and peer roles with equal access to tools"
        },
        {
          "id": "DC-09",
          "name": "Real-Time Collaboration",
          "description": "Live synchronized interaction across all participants"
        },
        {
          "id": "DC-10",
          "name": "Session Persistence",
          "description": "Sessions persist and can be resumed via invite link"
        }
      ],
      "floor_control": {
        "model": "Moderated turn-taking system",
        "rules": [
          "One active speaker at a time",
          "Queue-based participation for humans and AI",
          "Humans always take precedence over AI",
          "Bot moderator enforces order and resolves conflicts"
        ],
        "purpose": "Maintain clarity, prevent AI dominance, ensure human-centered decisions"
      },
      "choose_your_ai": {
        "mechanism": "Users select which AI models participate in the session",
        "vendor_value": [
          "Presence in high-stakes healthcare decisions",
          "Access to real-world healthcare interaction patterns",
          "Brand exposure at decision point"
        ],
        "platform_role": "Neutral host orchestrating multi-model interaction",
        "user_experience": "Transparent AI participation with visible model identities"
      },
      "pricing": "premium tokens + vendor partnerships",
      "role_in_value_chain": "revenue engine"
    }
  },
  "value_chain": {
    "flow": "Find -> Evaluate -> Discuss",
    "description": "Users begin by discovering providers (Find Care), build confidence through structured evaluation (Evaluate Care), and then move into collaborative decision-making with others and AI (Discuss Care). Each step increases engagement, trust, and context depth, culminating in high-value decision sessions."
  },
  "revenue_model": {
    "streams": [
      {
        "name": "AI Token Markup",
        "description": "Users pay for premium AI usage within Discuss Care sessions",
        "driver": "High-value, multi-participant decision contexts"
      },
      {
        "name": "AI Vendor Partnerships",
        "description": "AI providers pay for access to participate in healthcare decision sessions",
        "driver": "Distribution and presence in critical decision environments"
      },
      {
        "name": "Evaluate Care Premium (Future)",
        "description": "Advanced provider quality insights and comparative analytics behind paywall",
        "driver": "Established trust and demand for deeper analysis"
      }
    ],
    "gov_001_compliance": "All revenue originates from technology usage and AI vendors, not from providers, payers, or pharmaceutical companies. This preserves neutrality and aligns with Apple-style platform economics."
  },
  "moat": {
    "barriers": [
      "Regulatory positioning: AI vendors avoid direct exposure to healthcare regulation, creating dependency on a neutral platform",
      "Trust accumulation: healthcare decision trust compounds slowly and is difficult to replicate",
      "Data aggregation: multi-source provider and quality data requires long-term curation",
      "Governance framework: multi-AI safety, consent, and moderation system is non-trivial to design and operate",
      "Network effects: each session adds participants and behavioral signal",
      "Patent protection: LLM-based synthesis of provider quality signals"
    ]
  },
  "governance": {
    "policies": [
      "GOV-001: No care-chain revenue",
      "GOV-002: Single-tenant session isolation",
      "GOV-004: AI suggests, humans decide"
    ],
    "safety": "All components share a unified safety layer including healthcare scope enforcement, emergency detection, AI output constraints, and participant-level consent controls. Discuss Care adds moderation and floor control to ensure safe multi-party interaction."
  },
  "timeline": {
    "milestones": [
      {
        "date": "2026-04-30",
        "milestone": "Alpha launch (Find Care + Evaluate Care hardened)"
      },
      {
        "date": "2026-05-31",
        "milestone": "Discuss Care Beta Sprint 1"
      },
      {
        "date": "2026-07-31",
        "milestone": "Seed funding close"
      },
      {
        "date": "2026-08-25",
        "milestone": "Production launch"
      },
      {
        "date": "2026-09-20",
        "milestone": "Beta launch"
      }
    ]
  },
  "diagrams": {
    "component_diagram": {
      "description": "Three horizontally aligned boxes labeled Find Care, Evaluate Care, Discuss Care. Arrows flow left to right. Below all three is a shared layer labeled Data + AI Infrastructure (NPI, ClinicalTrials, State Boards, LLMs). On top is a Governance Layer spanning all components.",
      "elements": [
        "Box: Find Care",
        "Box: Evaluate Care",
        "Box: Discuss Care",
        "Arrow: Find Care -> Evaluate Care",
        "Arrow: Evaluate Care -> Discuss Care",
        "Layer below: Data + AI Infrastructure",
        "Layer above: Governance Layer"
      ]
    },
    "value_chain_diagram": {
      "description": "Linear flow with three stages: Discover, Assess, Decide. Each stage maps to Find Care, Evaluate Care, Discuss Care respectively. Increasing user engagement and value density shown as upward gradient.",
      "elements": [
        "Stage 1: Discover (Find Care)",
        "Stage 2: Assess (Evaluate Care)",
        "Stage 3: Decide (Discuss Care)",
        "Arrow progression left to right",
        "Value gradient increasing"
      ]
    },
    "revenue_flow_diagram": {
      "description": "Users on left, AI vendors on right, platform in center. Users send token payments to platform. AI vendors send partnership fees to platform. No arrows from providers/payers.",
      "elements": [
        "Entity: Users -> Platform (token payments)",
        "Entity: AI Vendors -> Platform (partnership fees)",
        "Platform: ChatHealthy",
        "No connection to care-chain entities"
      ]
    },
    "participant_model_diagram": {
      "description": "Central session box with multiple human participants and multiple AI agents connected. Moderator sits above enforcing rules. All participants connected to shared tool layer.",
      "elements": [
        "Node: Session",
        "Nodes: Human participants",
        "Nodes: AI models",
        "Node: Moderator",
        "Shared tool layer connection"
      ]
    },
    "care_decision_lifecycle": {
      "description": "Circular loop: Identify need -> Find providers -> Evaluate options -> Discuss with stakeholders -> Decide -> Re-engage if needed.",
      "elements": [
        "Step: Identify need",
        "Step: Find providers",
        "Step: Evaluate options",
        "Step: Discuss",
        "Step: Decide",
        "Loop back arrow"
      ]
    }
  },
  "competitive_landscape": "Search engines provide discovery but lack healthcare-specific evaluation. Provider directories offer listings without synthesis. Ratings platforms lack clinical depth and trust. Telehealth platforms focus on service delivery, not decision-making. AI companies provide general reasoning but avoid regulated healthcare contexts. None integrate multi-party collaboration, structured evaluation, and neutral governance in a single system.",
  "investment_thesis": "ChatHealthy.ai defines and owns the healthcare decision layer. By integrating discovery, evaluation, and collaborative decision-making, it captures the highest-value moment in healthcare: where choices are made. The platform's neutral revenue model aligns incentives, while AI vendor participation creates a scalable, defensible monetization path. With strong architectural foundations and clear governance, the company is positioned to become the default interface for healthcare decisions.",
  "sign_off": "Prepared for investor and partner review."
}
